-- Tuffy Flow: club seed data
--
-- Source: TitanLink, CSUF's student organization directory
--   https://fullerton.campuslabs.com/engage
--   One manual pull, 1 October 2026, from
--   /engage/api/discovery/search/organizations?top=100&orderBy[0]=Name asc&skip=N
--   The orderBy matters: without a stable sort the pages drift and 17 orgs come
--   back twice while 17 never come back at all.
--   701 total, curated to the 66 below. Every org in the directory is
--   Visibility: Public, so that part of the filter excludes nothing and the
--   Active count comes entirely from Status.
--
--   The directory moves. At the first pull 392 were Active; re-checked the same
--   afternoon it was 391, because Moving Forward Community @ CSUF had been
--   frozen. That one was dropped rather than left in, since a frozen club is
--   one nobody can join. Worth re-pulling before a demo.
--   Nothing in the app fetches TitanLink at runtime.
--
-- categories  TitanLink's CategoryNames, verbatim. Theirs.
-- tags        our own matching vocabulary. Ours, not a TitanLink field.
--             Mapped from their categories, plus keyword matching on the name
--             and description.
--             The word "programming" is deliberately not a keyword: in student
--             org writing it usually means events, not code, which is why Titan
--             TV does not come back as a software club. The "programming" tag
--             does exist, but it is reached through robotics terms instead.
-- Descriptions are TitanLink's with HTML stripped, so not byte for byte theirs.

-- Re-runnable: the real TitanLink rows are the only clubs that should exist.
delete from clubs;

insert into clubs (titanlink_id, name, summary, description, website_key, status, categories, tags) values
  ('134874', 'California Geotechnical Engineering Association', 'The purpose of this organization is to support initiative of the Geo-Institute to increase student membership and participation. Increase awareness among civil engineering undergraduates of the Geotechnical field and graduate school opportunities.', 'The purpose of this organization is to (a) provide opportunities for association and interaction with the faculty and administration of at CSU Fullerton. (b) Support initiative of the Geo-Institute to increase student membership and participation. (c) Increase awareness among civil engineering undergraduates of the geotechnical field and graduate school opportunities. (d) Facilitate planning of annual events within the department.', 'calgeo', 'Active', '{"College of Engineering and Computer Science"}', '{"engineering"}'),
  ('430732', 'Titan Product Management Club', 'Titan Product Management Club is a student organization dedicated to developing the next generation of product leaders through hands-on workshops, industry speaker events, and a community of driven peers passionate about building innovative products.', '', 'titan-product-management-club', 'Active', '{"College of Engineering and Computer Science","College of Business and Economics","Technology"}', '{"business","engineering","technology"}'),
  ('404632', 'National Organization of Black Chemists and Chemical Engineers', 'The purpose of this student chapter shall be consistent with the objectives NOBCChE. The objectives of NOBCChE, as established in the Certificate of Incorporation, are: to further the application of chemistry, chemical engineering and relate', 'The purpose of this student chapter shall be consistent with the objectives NOBCChE. The objectives of NOBCChE, as established in the Certificate of Incorporation, are: to further the application of chemistry, chemical engineering and related fields', 'nobcche', 'Active', '{"Cultural","College of Natural Science and Mathematics"}', '{"cultural","engineering"}'),
  ('135321', 'Institute of Transportation Engineers', 'The Institute of Transportation Engineers of California State University, Fullerton promotes education and professional development of those interested in transportation engineering.', 'We''re Cal State Fullerton''s prominent transportation engineering organization. We educate our members on the subject, develop their leadership and professional skills, and connect them with professionals and companies. Through many activities, such as resume workshops and Lunch-and-Learns, our club aims to help you secure internships and full-time jobs, all while fostering a sense of belonging. Our club size is not huge, so you''ll get more attention and seize more opportunities that will later h', 'ite', 'Active', '{"College of Engineering and Computer Science"}', '{"career","engineering","leadership"}'),
  ('181118', 'Student Academy of Audiology at California State University, Fullerton', 'The mission of the Student Academy of Audiology Chapter at CSUF is to advance the rights, interests, and welfare of students interested in pursuing a career in audiology.', 'The mission of the Student Academy of Audiology Chapter at CSUF is to serve as a collective voice for students within the chapter area and to advance the rights, interests, and welfare of students pursuing careers in audiology or related fields. The chapter will engage students in lifelong professional activities that promote and advance the profession of audiology and provide services, information, education, representation and advocacy for the profession and the public we serve. Feel free to c', 'saaatcsuf', 'Active', '{"Special Interest","College of Communications","Health & Wellness","Technology"}', '{"health-wellness","technology"}'),
  ('134228', 'American Society of Civil Engineers', 'ASCE is the nation''s oldest engineering society, and promotes success within the civil engineering field. Networking, educational tours, internships and social events are just a few things ASCE has to offer civil engineering students at CSUF.', 'ASCE is the nation''s oldest engineering society, and promotes success within the civil engineering field. CSUF ASCE has about 180 members and is a great opportunity not only to meet other students in your major but also to network with professionals within the field and advance your career. ASCE provides members with internship and job opportunites, networking events, educational seminars and tours, social events, and we work on a variety of projects. Our club is well known for our concrete cano', 'asce', 'Active', '{"Honor Society","Service","Special Interest","College of Engineering and Computer Science"}', '{"career","engineering","service"}'),
  ('145650', 'Titan TV', 'CSUF''s premier television channel, Titan TV, cable casts over Channel 98 on Time Warner Cable and AT&T U-Verse in Fullerton, Placentia, Santa Ana, Buena Park, Seal Beach, and Newport Beach.  Become a member to help boost awareness of Titan TV on campus.', 'Titan TV cable casts over Channel 98 on Spectrum (TWC) and AT&T U-Verse in Fullerton, Placentia, Santa Ana, Buena Park, Seal Beach, and Newport Beach as well as on the internet via titancomm.org. Titan TV broadcasts CSUF local origination programs such as In Focus, The Report, OC News, Titan Radio Live!, Al D&iacute;a, Tech On, Latino Communicators and other informational and educational programs. Titan TV also provides coverage of important University Events. All programming is crewed by talent', 'titantv', 'Active', '{"Special Interest","Career Planning","College of Communications","College of the Arts","Technology"}', '{"career","technology"}'),
  ('138410', 'CSUF Gaming & Esports', 'Gaming Club & Esports hopes to foster and promote a welcoming environment to introduce students at California State University, Fullerton to gaming culture.', 'CSUF Gaming & Esports is a club that offers many opportunities for members to express their passion for video games both competitively and socially. We provide a welcoming environment for all types of gamers at Cal State Fullerton to socialize with one another. Join our Discord here: https://discord.gg/nUGx5BntXT', 'csufesports', 'Active', '{"Service","Special Interest","Sport","Recreation","Social","Technology"}', '{"recreation","service","sport","technology"}'),
  ('135930', 'Business and Data Analytics Club', 'BDAC is a pan-university student organization that targets mainly on the technologies and innovations in the field of data sciences and business analytics.', 'The Business and Data Analytics Club (BDAC) at California State University, Fullerton is dedicated to providing ISDS students with opportunities to learn about tools and applications of data analysis and statistical methods to solve real-world business problems. BDAC is open to all CSUF students who are interested in data-oriented careers. We welcome undergraduates, graduate, and MBA students who are interested in data science, data analytics, business analytics, informational systems, and decis', 'bdac', 'Active', '{"Special Interest","College of Business and Economics","Technology"}', '{"business","data-science","technology"}'),
  ('382503', 'Adobe @ Fullerton', 'This club is to have a creative space for students to express themselves through art using Adobe''s programs from the Creative Cloud. Students can socialize with fellow peers in the club while doing recreational activities.', 'The purpose of this organization is to have a creative space for students to express themselves through Adobe''s programs within the Creative Cloud. Students can do this by participating in workshops to help develop their skills using available applications in the Creative Suite that are free for all CSUF students. Students can socialize with fellow peers in the club while doing recreational activities.', 'adobe_fullerton', 'Active', '{"Special Interest","Recreation","College of the Arts","College of Business and Economics","Social","Technology"}', '{"business","recreation","technology"}'),
  ('403163', 'Titan Underwater Robotics at California State University, Fullerton', 'Titan Underwater Robotics at CSUF, sponsored by RJE International, Inc., develops innovative submersible vehicles for ROV competitions, advancing marine robotics through collaborative student projects.', 'The purpose of this organization is to foster innovation and excellence in underwater exploration technologies. Sponsored by RJE International, Inc., the club serves as a collaborative pipeline, beginning with foundational projects in the Computer Engineering Senior Design Program and inviting underclassmen to carry these initiatives forward, building on prior advancements each year. Our primary focus is the design and development of cutting-edge submersible vehicles to compete in the annual ROV', 'titanunderwaterrobics', 'Active', '{"College of Engineering and Computer Science","Technology"}', '{"engineering","programming","technology"}'),
  ('414916', 'Technology and Business solutions', 'Tech & Business Solutions Club: We explore tech-driven business strategies through software services, mock business modeling, and data analysis. Hands-on learning for future innovators.', 'Technology and Business Solutions (TBS) is a dynamic organization dedicated to bridging the gap between technology and business innovation. We provide hands-on experience in electronic software services, business development, and data-driven decision-making. Through mock business models, real-world case studies, and collaborative projects, we empower members to develop practical skills in entrepreneurship, digital solutions, and strategic business analysis. Whether you''re interested in tech, sta', 'tbsclub', 'Active', '{"Fraternity & Sorority","Career Planning","College of Engineering and Computer Science","College of Business and Economics","Technology"}', '{"business","career","engineering","startups","technology"}'),
  ('424998', 'Marvel Rivals Club', 'Marvel Rivals Club brings CSUF students together through Marvel Rivals for social gameplay, strategy discussions, and optional student-run events. We welcome all skill levels and aim to build community while helping new players learn the game.', 'Our club, Marvel Rivals Club , is for CSUF students who love the game Marvel Rivals. We focus on bringing people together for social gameplay, talking strategy, and optional student-run events. Our goal is to build a community and get people involved, and we''d love to teach new players the game as well. While we do organize gameplay groups, participation is completely optional and open to everyone, no matter their skill level. Our Discord: https://discord.com/invite/vECDun5dsv', 'csufrivals', 'Active', '{"Special Interest","Social","Technology"}', '{"technology"}'),
  ('136381', 'American Society of Mechanical Engineers', 'ASME is an organization that enables collaboration, knowledge sharing, career enrichment, and skills development across all engineering disciplines. This organization is represented explicitly by California State University Fullerton students.', 'The purpose of this organization is to provide its members opportunities to gain broader insight into the mechanical engineering profession by sponsoring meetings which will bring practicing engineers to the campus, arranging field trips to research and engineering establishments, sponsoring student projects of engineering interest, and participating in local ASME Section activities. It shall also be the purpose of this organization to encourage good fellowship among engineering students and the', 'asme', 'Active', '{"Special Interest","College of Engineering and Computer Science","Social","Technology"}', '{"engineering","technology"}'),
  ('133035', 'National Society of Black Engineers; California State University, Fullerton Chapter', 'The National Society of Black Engineers is a non-profit student run organization. Our mission is to increase the number of culturally responsible black engineers who excel academically, succeed professionally, and positively impact the community.', 'The purpose of the National Society of Black Engineers (NSBE); California State University, Fullerton (CSUF) Chapter is to stimulate and develop student interest in engineering, strive to increase the number of students studying engineering at both the undergraduate and graduate levels; and to endeavor in the advancement of the ethnic minority engineer within the professional industry.', 'nsbecsuf', 'Active', '{"Cultural","College of Engineering and Computer Science"}', '{"cultural","engineering"}'),
  ('135973', 'Society of Hispanic Professional Engineers', 'The vision of SHPE at CSUF is a world where our members are highly valued and influential as the leading innovators, scientists, mathematicians and engineers.', 'SHPE at CSUF is a student-driven organization at the College of Engineering and Computer Science (ECS) that strives to leave a lasting impact on its members. Our mission is to develop and strengthen the next generation of Innovators, Scientists, Mathematicians, and Engineers through STEM awareness, access, support, and development. SHPE at CSUF provides its member''s opportunities to network with professionals, access to workshops, along with attending regional and national conventions. Not only ', 'csufshpe', 'Active', '{"Cultural","Special Interest","Career Planning","College of Engineering and Computer Science","Social","Technology"}', '{"career","cultural","engineering","leadership","technology"}'),
  ('138103', 'Fullerton Motor Group', 'Fullerton Motor Group is a place for car enthusiasts, advocates, and people with general interests in automotive technologies to discuss, educate, and help others with automotive interests.', 'Fullerton Motor Group (FMG) is CSUF''s premier auto enthusiast club! We are a social-recreational and educational club dedicated to providing a platform for all vehicle enthusiasts to discuss with others all things car-related. We enable car people to express their passions at weekly events/group drives and a lively discord server, while promoting the proper education of vehicle maintenance, safety, and driving techniques. FMG strives to make a welcoming community for all auto enthusiast students', 'fullertonmotorgroup', 'Active', '{"Special Interest","Sport","Recreation","Outdoors","Social","Technology"}', '{"outdoors","recreation","sport","technology"}'),
  ('138169', 'Society of Women Engineers', 'We are an organization that supports diversity in engineering and technology, through outreach, volunteering and community service.', 'Stimulate women to achieve full potential in careers as engineers and leaders, expand the image of the engineering profession as a positive force in improving the quality of life, and demonstrate the value of diversity.', 'swe', 'Active', '{"Political/Social Action","Service","College of Engineering and Computer Science","Technology"}', '{"engineering","political-social-action","service","technology"}'),
  ('135443', 'Tau Beta Pi California Chi Chapter', 'Tau Beta Pi is the only engineering honor society representing the entire engineering profession. It is the nation''s second-oldest honor society, founded at Lehigh University in 1885.', 'Tau Beta Pi is the only engineering honor society representing the entire engineering profession. It is the nation''s second-oldest honor society, founded at Lehigh University in 1885 to mark in a fitting manner those who have conferred honor upon their Alma Mater by distinguished scholarship and exemplary character as students in engineering, or by their attainments as alumni in the field of engineering, and to foster a spirit of liberal culture in engineering colleges. Our local Chapter here a ', 'tbp', 'Active', '{"Honor Society","College of Engineering and Computer Science","Sustainability","Technology"}', '{"engineering","sustainability","technology"}'),
  ('135857', 'Super Smash Brothers Club', 'The Smash Club of CSUF is a club to help grow and bring together the local community of students interested in the Super Smash Bros. franchise and engage in social events that encourage friendly competition and community building.', 'Our club''s goal is to help bring together the Super Smash Bros franchise to the students who are interested in learning in a competitive way and built a community around it. Our meetings consist of friendly grind session and we also host weekly tournaments. In addition, we will have fun events such as doubles, crew battles, squad strike, and even other Smash franchises.', 'csufsmash', 'Active', '{"Cultural","Special Interest","Recreation","LGBTQ+","Social","Technology"}', '{"cultural","lgbtq","recreation","technology"}'),
  ('137065', 'Association for Computing Machinery - Women', 'ACM-W celebrates & advocates for the full engagement, education, & opportunities of women in all aspects of the computing field. We endeavor to provide a wide range of programs/services to students & advance the contributions of technical women students.', 'Association for Computing Machinery - Women supports, celebrates, and advocates for the full engagement, education, and opportunities of women in all aspects of the computing field. We endeavor to provide a wide range of programs and services to students and advance, in the larger community, the contributions of technical women students. Join our Discord server to check out when our next event is! Join our Discord here! Check us out on Instagram Here! Visit Our Website! Here!', 'acmw', 'Active', '{"College of Engineering and Computer Science","College of Natural Science and Mathematics"}', '{"engineering","software-engineering"}'),
  ('137052', 'Society of Automotive Engineering - Formula', 'SAE is California State University, Fullerton’s Formula Titan Racing team and one of the university’s premier engineering legacy organizations. Members gain hands-on experience in designing, manufacturing, testing, and competing with a Formula SAE car.', 'SAE is California State University, Fullerton''s Titan Racing Formula SAE team and one of the university''s premier engineering legacy organizations. The club gives students hands-on experience in designing, manufacturing, testing, and competing with a formula-style race car in the international Formula SAE Collegiate Design Series. Members work across multiple subteams, including suspension, chassis, aerodynamics, powertrain, electrical, and vehicle dynamics, while also gaining experience in team', 'fsae', 'Active', '{"Special Interest","Recreation","College of Engineering and Computer Science","Technology"}', '{"business","engineering","recreation","technology"}'),
  ('135175', 'Institute of Navigation', 'The Institute of Navigation is supported by the Electrical Engineering department in advancing the field of GPS and navigational technologies. In addition, this club focuses on engineering competitions that utilize navigation such as autonomous robotics.', 'The Institute of Navigation at California State University of Fullerton is established and organized as a scientific society, designed to advance the art and science of navigation through regional and national meetings, newsletters, and through its officers and working committees. The Institute of Navigation at California State University, Fullerton shall be a student branch of the Institute of Navigation Southern California Section.', 'ion', 'Active', '{"Special Interest","College of Engineering and Computer Science","Technology"}', '{"engineering","programming","technology"}'),
  ('136539', 'Offensive Security Society', 'To catch a criminal, you need to think like one. At OSS, we teach you the necessary skills to accomplish this over cyberspace to become an ethical hacker. Learn and network with CSUF Students brought together by Cybersecurity interest!', 'OSS offers an entry point into the field of offensive and defensive cybersecurity - a proactive and adversarial approach to protecting computer systems, networks, and individuals from attacks. At OSS, you will learn the basic real-world skills needed to succeed and become a cybersecurity professional. Some topics we cover throughout the school year in our weekly workshop meetings include Web Application penetration testing, Windows Active Directory attacks, lockpicking, Application Security, Sys', 'oss', 'Active', '{"Special Interest","College of Engineering and Computer Science","Technology"}', '{"cybersecurity","engineering","technology"}'),
  ('132823', 'Data Science and Machine Learning', 'The Data Science and Machine learning club''s mission is to create an inclusive environment to network, and foster growth and interest in Technology and its practical uses from data science and machine learning techniques.', 'The purpose of this club is to organize meetings to share knowledge and experience about Machine Learning, Data Science, and Business Intelligence. Also, we are planning to host industry events, workshops, and Machine Learning/Data competitions/Projects. If you are interested in the club, please select the Join button through TitainLink. If you have any questions please email us at csufdsml@gmail.com. Also please join the discord to get up-to-date information regarding the club and its future me', 'machine-learning-and-data-science-club', 'Active', '{"Special Interest","College of Engineering and Computer Science","College of Business and Economics","Technology"}', '{"ai","business","data-science","engineering","technology"}'),
  ('297863', 'Society for the Advancement of Material and Process Engineering CSUF Chapter', 'The Society for the Advancement of Material and Process Engineering (SAMPE®) is a global professional member society that provides enhanced educational opportunities, by delivering information on new and advanced materials and processing technology.', 'The Society for the Advancement of Material and Process Engineering (SAMPE&reg;) is a global professional member society that provides enhanced educational opportunities, by delivering information on new and advanced materials and processing technology. SAMPE provides growth and educational opportunities via conferences, exhibitions, technical forums, and publications. As the only technical society encompassing all fields of endeavor in materials and processes, SAMPE provides a unique and valuab', 'sampe', 'Active', '{"Special Interest","College of Engineering and Computer Science","Technology"}', '{"engineering","technology"}'),
  ('349456', 'United States Institute for Theatre Technology, Inc. Student Chapter at California State University, Fullerton', 'The CSU Fullerton USITT Student Chapter was established to provide opportunities for students wishing to further their experience in technical theatre, design, and management through education, outreach, and networking.', 'USITT was founded in 1960 as an organization to promote dialogue, research, and learning among practitioners of theatre design and technology. Today it has grown to include members at all levels of their careers and has embraced the new technologies being used in entertainment. Our goal as a club is to connect students to working theater professionals through tours, workshops, and master classes. We create fundraising opportunities in order to get students to go to the USITT conference every yea', 'usittcsuf', 'Active', '{"Special Interest","College of the Arts","Technology"}', '{"technology"}'),
  ('332118', 'Augmentative & Alternative Communication Club', 'Not everyone can communicate through speech. Our mission is to educate others on augmentative and alternative communication (AAC), the form of communication used by those who cannot solely rely on speech for effective communication.', 'Our Mission: To serve as an avenue for students to learn about aided augmentative and alternative communication (AAC) and to serve as a general information resource on AAC for the university and the local community. As the AAC Club, our goal is to educate future professionals and the community about augmentative and alternative communication (AAC). Complex communicators, those who cannot rely solely on speech for effective communication, use AAC to communicate effectively. If you are interested ', 'aac', 'Active', '{"College of Communications","College of Education","College of Health and Human Development","Health & Wellness","Technology"}', '{"health-wellness","technology"}'),
  ('136541', 'Titan Rover', 'Titan Rover is an interdisciplinary collaboration of students from multiple backgrounds with an interest in extraterrestrial robotic and scientific applications. Our goal is to qualify and compete in the Mars Society''s annual University Rover Challenge.', 'Titan Rover began as an electrical engineering project. Over time, Titan Rover has expanded to include students with backgrounds in: Mechanical Engineering, Computer Engineering, Computer Science, Biology, Geology, Business, Chemistry, Photography, Film, Graphic Design, Marketing, etc. Thus there was a recognized need to expand the project into a club in order to be a home to anyone who has an interest in robotics, space, science, engineering, or the inhabitation of Mars. If you are interested i', 'titanrover', 'Active', '{"Special Interest","Career Planning","College of Engineering and Computer Science","College of Natural Science and Mathematics","College of Business and Economics","Social","Technology"}', '{"business","career","engineering","programming","software-engineering","technology"}'),
  ('132967', 'Video Game Development Club', 'The Video Game Development Club at CSUF is an organization aimed at aspiring game developers, artists, composers, and any other individuals looking to apply their skills with like-minded students to create interactive applications and games.', 'The Video Game Development Club at CSUF is an organization aimed at aspiring game developers, artists, composers, writers, and any other individuals looking to apply their skills with like-minded students to create interactive applications and game media. Each semester, members of the club will have the opportunity to create their own games, lead projects, and collaborate with other club members to create something amazing! The club will also be hosting many events, such as: studio tours of near', 'vgdc', 'Active', '{"Special Interest","Recreation","Career Planning","College of Engineering and Computer Science","College of the Arts","LGBTQ+","Music","Social"}', '{"career","engineering","game-dev","lgbtq","music","recreation"}'),
  ('348878', 'ACM SIGGRAPH', 'ACM SIGGRAPH is a student chapter focused on fostering a diverse community for students interested in the future of computer graphics, interactive techniques, and emerging technologies associated with ACM SIGGRAPH.', 'ACM SIGGRAPH is a student chapter focused on fostering a diverse membership community for students at CSU Fullerton that promotes and inspires researchers, artists, developers, filmmakers, and scientists whose core values help to shape the future of computer graphics, interactive techniques, and emerging technologies in the specialized fields associated with ACM SIGGRAPH. Chapter members may be interested in careers in animation, games, VR/AR, scientific research, software development, visual ef', 'csufacmsiggraph', 'Active', '{"Special Interest","College of Engineering and Computer Science","College of the Arts","Technology"}', '{"engineering","software-engineering","technology"}'),
  ('332185', 'The SIAM Student Chapter at California State University, Fullerton', 'The SIAM Student Chapter provides opportunities for students to participate in a national organization, benefit from its resources, foster connections with members of industry, and explore opportunities for pursing careers in applied mathematics.', 'The Society of Industrial and Applied Mathematics (SIAM) is an internationally recognized organization designed to promote the application of mathematics and computational science to engineering, industry, science, and society. SIAM organizes regular conferences, outreach activities, journal publications, internships, fellowships, and networking opportunities. The purpose of the SIAM Student Chapter at CSUF is to provide opportunities for undergraduate and graduate students interested in applied', 'siamstudentchaptercsuf', 'Active', '{"Career Planning","College of Natural Science and Mathematics"}', '{"career","engineering"}'),
  ('381813', 'Women In Business & STEM', 'The Women in Business and STEM club supports student career and personal growth through resume help, webinars with industry experts, leadership roles, study groups, community service, and public speaking training. 
Website: https://wibscsuf.com', 'The Women in Business and STEM Club is a dynamic student organization committed to enhancing career and personal growth. We provide resources such as resume assistance, mock interviews, and expert-led webinars on finance and technology. Through leadership roles, study groups focusing on the latest trends, community engagement, and public speaking training, we foster essential professional skills and boost confidence in professional settings, ensuring students are well-equipped to excel in their ', 'womeninbusinessstem', 'Active', '{"Cultural","Special Interest","Career Planning","College of Engineering and Computer Science","College of Natural Science and Mathematics","College of Business and Economics","Social","Technology"}', '{"business","career","cultural","engineering","leadership","technology"}'),
  ('132479', 'Titan Racing', 'The purpose of this organization is to provide engineering opportunities for students at CSU Fullerton and to build an SAE approved mini baja for competition.', 'Baja SAE&reg; consists of competitions that simulate real-world engineering design projects and their related challenges. Engineering students are tasked to design and build an off-road vehicle that will survive the severe punishment of rough terrain. The object of the competition is to provide SAE student members with a challenging project that involves the design, planning and manufacturing tasks found when introducing a new product to the consumer industrial market. Teams compete against one ', 'titanracing', 'Active', '{"Special Interest","Career Planning","College of Engineering and Computer Science","Technology"}', '{"career","engineering","technology"}'),
  ('137313', 'Association for Computing Machinery', 'We are the largest Computer Science community at CSUF. Our chapter provides workshops, career resources, and a social community that''s open to all majors.

Join us on Discord at acmcsuf.com/discord', 'General ACM events are every Thursday at 5:30pm! acmCSUF is a student chapter of the Association for Computing Machinery, an international organization dedicated to advancing computing as a science and profession. Our chapter brings together students at California State University, Fullerton who are passionate about tech through hands-on workshops, industry info sessions, socials, and more. Our chapter is open to anyone interested, regardless of major or background experience. Join our community', 'acm', 'Active', '{"Career Planning","College of Engineering and Computer Science","Social","Technology"}', '{"career","engineering","software-engineering","technology"}'),
  ('181143', 'Theta Tau', 'Theta Tau is a professional co-ed Engineering Fraternity for all type of engineers and computer science. Its main goal is to develop and maintain a high standard of professional interest among its members and to unite them in a strong bond of fellowship.', 'Theta Tau ( &Theta;&Tau; ) is a co-ed professional engineering fraternity. As defined by the fraternity, "The purpose of Theta Tau is to develop and maintain a high standard of professional interest among its members, and to unite them in a strong bond of fraternal fellowship." The goals of the fraternity are to promote the social and professional development of its members during and after their college years. Today, Theta Tau is the oldest and largest professional engineering fraternity in the', 'thetatau', 'Active', '{"Fraternity & Sorority","Service","Career Planning","College of Engineering and Computer Science"}', '{"career","engineering","service"}'),
  ('365843', 'Backcountry Hunters and Anglers Chapter at Cal State University, Fullerton', 'BHA is an organization of sportsmen and women dedicated to work on behalf of public lands and waters. They achieve this through their focus on three areas: access & opportunity, public lands and waters, and fair chase.', 'BHA''s Collegiate Program is built upon 5 pillars: Community: Our public lands and waters are best shared with friends We are committed to building a community of conservation minded young adults who value our public lands, waters, wildlife, and hunting and angling heritage. Within each university, our clubs strive to create a group of friends and acquaintances who share their passions for the outdoors through hunting, angling, or any other activity enjoyed on our public lands and waters. People ', 'backcountry-hunters-anglers-csuf', 'Active', '{"Political/Social Action","Service","Special Interest","Sport","Recreation","Health & Wellness","Outdoors","Social","Sustainability"}', '{"health-wellness","outdoors","political-social-action","recreation","service","sport","sustainability"}'),
  ('136279', 'Dance Association', 'Dance Association provides a greater opportunity for members to become involved in the Dance and Theater Department, along with the campus community.', 'The purpose of Dance Association is to provide students of all majors an opportunity to dance and to find a community of supportive, like-minded individuals. Our club''s major focus is to provide students with free pop-up classes and master classes taught by students, alumni, and guest artists. We also offer mentorship and onboarding for new students, as well as leadership experience. In addition, DA hosts concessions during performances and other fundraisers to provide scholarships and funding f', 'danceassociationcsuf', 'Active', '{"Special Interest","Sport","Recreation","Career Planning","College of the Arts","Dance","Health & Wellness","Social"}', '{"career","dance","health-wellness","leadership","mentorship","recreation","sport"}'),
  ('295451', 'Ascend Leadership at CSUF', 'Empowering the Next Generation of AAPI Business Leaders at CSUF', 'Since 2025, Ascend CSUF has helped students turn ambition into opportunity. As the Cal State Fullerton chapter of Ascend, the largest nonprofit organization for Pan-Asian business professionals and students in North America, the club connects members to a network of more than 100,000 individuals across 65 chapters. Through its partnership with Ascend OC, students gain direct access to professionals and executives from leading firms across a wide range of industries. Members develop the confidenc', 'ascendcsuf', 'Active', '{"Cultural","Career Planning","College of Business and Economics"}', '{"business","career","cultural","leadership","mentorship"}'),
  ('132624', 'The Teaching English to Speakers of Other Languages Club of California State University, Fullerton', 'Providing resources and opportunities on how to teach English to speakers of other languages. A place to network and exchange ideas; we focus on developing professional knowledge of language teaching and expanding intercultural inclusion and awareness.', 'The Teaching English to Speakers of Other Languages (TESOL) Club is dedicated to serving the students of California State University, Fullerton by providing excellent academic opportunities to develop professional expertise in the field of ESL/EFL education and cultural enrichment through connecting with our multi-ethnic association. A community-minded organization, our heart is to positively influence and impact teachers and students alike. Every semester, we regularly host and promote Project ', 'tesol', 'Active', '{"Cultural","Political/Social Action","Service","Special Interest","Recreation","Career Planning","College of Humanities & Social Sciences","Social"}', '{"career","cultural","political-social-action","recreation","service"}'),
  ('430903', 'Psychology Student Support Club', 'The Psychology Student Support Club (PSSC) is always on standby and ready to assist all California State University, Fullerton students to facilitate a safe space for unity and an opportunity for all.', 'The Psychology Student Support Club, led by faculty advisor Professor Madracki (M.S., LMFT), bridges the gap between students, faculty, and other psychology student-led organizations and associations in support of students throughout their time at California State University, Fullerton. Whether it be connecting with other peers, faculty, other college departments on campus, to internal and external support resources, to managing the multitude of sentiments that go along with being a college stud', 'psychologystudentsupportclub', 'Active', '{"Cultural","Career Planning","College of Humanities & Social Sciences","Health & Wellness","LGBTQ+","Social","Sustainability"}', '{"career","cultural","health-wellness","lgbtq","sustainability"}'),
  ('433268', 'Latinas Leading in Advocacy & Defense', 'Empowering Latina women in criminal justice by creating a space where they feel seen, supported, and represented. We promote education, confidence, and career success while helping members overcome cultural and educational barriers.', 'Latinas LE.A.D. (Leading in Advocacy & Defense) is an organization dedicated to empowering Latina women in criminal justice by creating a space where they feel seen, supported, and represented. We promote education, confidence, and career success while helping members overcome cultural and educational barriers. Our mission is to inspire and uplift Latina students through mentorship, networking opportunities, professional development, and community engagement. By fostering leadership, advocacy, a', 'latinasleadcsuf', 'Active', '{"Cultural","Career Planning","College of Education","College of Humanities & Social Sciences","Health & Wellness","Social"}', '{"career","cultural","health-wellness","leadership","mentorship"}'),
  ('132736', 'Latino Business Student Association', 'We, the Latino Business Student Association (LBSA), are more than a club, we are a familia. Our organization revolves around professional development, networking, and community service. Our goal is to help our members become community leaders.', 'The Latino Business Student Association ( LBSA ) is a student led organization at College of Business and Economics of CSUF where we work to create future business leaders, through professional and social networking. Whether you''re a student looking to get involved or a business professional looking for student leaders, you need an organization that helps you connect to the community so you can establish rapport at the grassroots level. Our goal is to develop diverse leaders who conscientiously ', 'lbsa', 'Active', '{"Cultural","Service","Career Planning","College of Business and Economics","Social"}', '{"business","career","cultural","leadership","service"}'),
  ('429512', 'Global Medical Brigades at CSUF', 'Global Medical Brigades at CSUF raises funds to support annual medical mission trips, allowing students to volunteer in underserved communities, shadow local physicians, assist with pharmacy operations, and lead health education workshops globally.', 'Global Medical Brigades at CSUF is a student‑led chapter committed to advancing access to healthcare and supporting sustainable healthcare initiatives in underserved communities worldwide. As part of the international Global Brigades network, our chapter empowers pre‑health and globally minded students to engage in ethical, community‑based global health work through education, fundraising, and hands‑on service. Throughout the academic year, members participate in community service, training, pro', 'gmbcsuf', 'Active', '{"Political/Social Action","Special Interest","Career Planning","College of Health and Human Development","College of Humanities & Social Sciences","College of Natural Science and Mathematics","Health & Wellness","Social","Sustainability"}', '{"career","health-wellness","political-social-action","sustainability"}'),
  ('424638', 'Live Action at California State University, Fullerton', 'Live Action at CSUF is a chapter of the national, non-profit organization founded in 2003 by Lila Rose. We are dedicated to building a culture of life on campus and beyond through community service, outreach, and social efforts.', 'Live Action at CSUF is a chapter of the national, non-profit organization founded in 2003 by Lila Rose dedicated to ending abortion and building a culture of life. Through education, service, and outreach, this chapter will defend the inherent dignity of all human life, particularly the preborn, educate our peers in the horrors of the abortion industry, and mobilize the Titan community in pro-life efforts. We will make abortion unthinkable by sharing factual information about abortion, promoting', 'csuf-liveaction', 'Active', '{"Political/Social Action","Faith","Service","Special Interest","Health & Wellness"}', '{"faith","health-wellness","political-social-action","service"}'),
  ('203288', 'Society for the Advancement of Chicanos/Hispanics and Native Americans in Science at California State University, Fullerton', 'SACNAS is a national society that fosters the success of persons from groups historically under-represented in science and seeks to improve and expand opportunities for students in the scientific workforce and academia.', 'SACNAS (Society for the Advancement of Chicanos/Hispanics and Native Americans in Science) is a national organization dedicated to "True diversity in STEM. True diversity means that the field (including leadership positions) reflects the demographics of the population." We envision a CSUF SACNAS chapter as an opportunity for students from all STEM fields to build community. Members would span experience levels from first year undergraduates to graduate students. From the SACNAS website ( www.sac', 'sacnascsuf', 'Active', '{"Cultural","Service","Special Interest","College of Natural Science and Mathematics","Social"}', '{"career","cultural","leadership","service"}'),
  ('134512', 'Master of Social Work Association', 'MSWA aims to empower MSW students through community, peer support, and professional development.', 'MSWA is dedicated to empowering MSW students at CSUF by fostering a strong sense of community, peer support, and professional growth. Through a variety of events, programs, and opportunities, we create spaces for graduate students to connect, gain experience, and build meaningful networks. Members benefit from opportunities such as participating in our peer mentor program, serving as cohort representatives, and accessing a range of organizational resources. Grounded in values of kindness, empath', 'mswacsuf', 'Active', '{"Political/Social Action","Service","Special Interest","College of Health and Human Development","Health & Wellness","Social"}', '{"career","health-wellness","political-social-action","service"}'),
  ('134772', 'Kinesiology Student Association', 'The Kinesiology Student Association (KSA) works to provide support and guidance to create a comfortable environment for students to exchange ideas, skills, and knowledge regarding all aspects of the field of Kinesiology.', 'The Kinesiology Student Association (KSA) works to provide support and guidance to create a comfortable environment for students to exchange ideas, skills, and knowledge regarding all aspects of the field of Kinesiology. KSA helps students share relevant academic experiences with one another, educates its members regarding entrance requirements to various Allied Health graduate programs, and provides networking opportunities through various guest speakers, collaborations with other health-relate', 'ksa', 'Active', '{"Sport","College of Health and Human Development","Health & Wellness","Outdoors","Social"}', '{"career","health-wellness","outdoors","sport"}'),
  ('135038', 'Geography Club of CSUF', 'The Geography Club of CSUF is an organization of students who share interests in humanity''s relations with the natural world, our built environment and cultures. As a club we facilitate activities exploring our natural, urban and cultural landscapes.', 'Welcome to Geography Club of CSUF! Whether you like outdoor activities, helping the environment, social networking, or just hanging out with friends, you''ll fit right in with other members. There is no need to be a Geography major to join the club, and there are no fees! Join our discord account at: https://discord.gg/QMWpfrD The Geography Club of CSUF Discord is a place where alumni, students, and professors can all keep in touch. There are different channels such as the lounge, geography adven', 'geographyclubofcsuf', 'Active', '{"Special Interest","Recreation","College of Humanities & Social Sciences","Outdoors","Social","Sustainability"}', '{"career","outdoors","recreation","sustainability"}'),
  ('226015', 'Planned Parenthood Generation Action at CSUF', 'Our club is committed to educating and advocating issues of reproductive rights and freedoms, while prioritizing inclusivity and political action.', 'Planned Parenthood Generation Action at CSUF is a network of young activists who organize events on their campus and in their community to: Mobilize advocates for reproductive freedom Raise public awareness about reproductive health and rights Educate young people about sexual health Create lasting change in their communities To communicate with our club members about meetings and events we will use discord (the app) and our Instagram page. Discord Code: https://discord.gg/vS7EqztrSH Instagram n', 'csufppgen', 'Active', '{"Political/Social Action","Service","Health & Wellness","LGBTQ+"}', '{"health-wellness","lgbtq","political-social-action","service"}'),
  ('135401', 'Flying Samaritans', 'Flying Samaritans at CSUF is a sub-chapter of the larger Palomar Chapter of the Flying Samaritans organization that intends to aid in the provision of free medical and vision care to the citizens of Mexico who lack health care.', 'Our Mission Flying Samaritans at CSUF is a sub-chapter of the larger Palomar Chapter of the Flying Samaritans organization that intends to aid in the provision of free medical care to the citizens of Mexico who lack health care. We also present an opportunity for pre-health students, social sciences students, and Spanish translators to gain international volunteer experience. How to Become a Member Simply click the Join Us! and fill your information on the form. Please use a valid email address ', 'flyingsams', 'Active', '{"Service","Special Interest","Career Planning","College of Health and Human Development","College of Natural Science and Mathematics","Health & Wellness","Social","Sustainability"}', '{"career","health-wellness","service","sustainability"}'),
  ('135737', 'College Republicans at California State University Fullerton', 'A strong community of open dialogue, leadership, and conservative values. 
Meetings : Tuesday at 5:30 pm 
 - Internships, volunteering, public speaking , and networking 
IG : @csufrepublicans 
E-mail : titan.csufrepublicans@gmail.com', 'The College Republicans at Cal State Fullerton is a student-led organization that promotes free speech, respectful dialogue, and political engagement. We believe university communities should be places where diverse ideas are heard and discussed &mdash; not ignored or shut down. Our goal is to create a welcoming space for students to express their views, learn from others, and grow through meaningful conversations. Encouraging thoughtful and open conversation, even when opinions differ, is one o', 'csufrepublicans', 'Active', '{"Political/Social Action","Service","Special Interest","Career Planning","Social"}', '{"career","leadership","political-social-action","service"}'),
  ('135468', 'French Club', 'The purpose of this organization is to promote learning, community, and improved understanding and performance of: French language, French culture, and the CSUF French program(s).', 'The purpose of this organization is to promote learning, community, and improved understanding and performance of: French language, French culture, and the CSUF French program(s). We also seek to provide opportunities for association, interaction, and learning from fellow students, faculty, administration, and guest speakers at CSU Fullerton. As well as to promote practices involving intercultural communication, friendship, and other forms of enrichment.', 'frenchclub', 'Active', '{"Political/Social Action","Special Interest","Recreation","Career Planning","College of Communications","College of Humanities & Social Sciences","Music"}', '{"career","music","political-social-action","recreation"}'),
  ('132783', 'Student Veterans of America', 'The purpose of this organization is to cultivate a sense of belonging among student veterans in higher education to foster success on and off campus.', 'We are the Student Veterans of America (SVA) at California State University Fullerton (CSUF). We strive to connect local veteran organizations with our student veterans through volunteering and networking. This organization is affiliated with Student Veterans of America, which is a national non-profit organization that advocates for student veterans through legislation and policy in Washington D.C.', 'studentveteransassociation', 'Active', '{"Service","Special Interest","Recreation","Career Planning","College of Humanities & Social Sciences","Outdoors","Social"}', '{"career","outdoors","recreation","service"}'),
  ('137490', 'CSUF Surf Club', 'The main focus of this club is to bring the surfers, bodyboarders and bodysurfers from CSUF together. We will have planned surf meets and events. Our goal is to not only have people enjoy the ocean but also respect it as well.', 'Hey everyone! This is a simple club where we meet up, meet new people and all paddle out together. We send emails but the very best way to be in the know is by filling out our interest form in our instagram bio @csufsurfclub. Through there we plan out events. Hope to see you out there! We can teach when available but this club is not recommended for first timers. There is no fee to join but student must provide a board and transportation. The goal of the club is to meet once a week at the beache', 'csufsurfclub', 'Active', '{"Special Interest","Sport","Recreation","Health & Wellness","Outdoors","Social"}', '{"health-wellness","outdoors","recreation","sport"}'),
  ('135859', 'Glass Club of CSUF', 'The Glass and Metal Club of CSUF promotes education of awareness of glass art by sponsoring guest lectures and demonstrations by qualified glass artists and historians. The club also disseminates information promotion.', 'The purposes of the Glass Club of CSUF are to promote education concerning glass art by sponsoring guest lectures and slide presentations by qualified glass artists, historians, and visionaries; to promote Glass arts, by disseminating information, promoting student exhibitions and Fund Raising Glass Sales, participating in campus outreach programs, mentoring beginning Glass students and community involvement. Weekly Meetings - TBA - Hotshop VA-B130', 'glassclubofcsuf', 'Active', '{"Cultural","Special Interest","Recreation","Career Planning","College of Education","College of the Arts"}', '{"career","cultural","mentorship","recreation"}'),
  ('132719', 'Behind The Scenes', 'BTS provides students in the Entertainment & Hospitality Management program with opportunities to interact with fellow students, professors, as well as with members of the Entertainment and Hospitality industries through VIP tours, panels, workshops.', 'This student-led organization provides students in the Entertainment & Hospitality Management concentration with opportunities for association and interaction with fellow peers, professors, as well as with members of the Entertainment and Hospitality Industries. Furthermore, the purpose of the club is to foster leadership and create a competitive advantage for members. Interests include music, film, TV, video games, live events, hospitality, casinos, etc.', 'behindthescenes', 'Active', '{"Service","Special Interest","Sport","College of Business and Economics","Music","Social"}', '{"business","leadership","music","service","sport"}'),
  ('413299', 'Phi Delta Theta', 'Phi Delta Theta Alpha Alpha promotes leadership, academic excellence, and community service among its members. Our fraternity emphasizes lifelong brotherhood and personal development.', 'Phi Delta Theta is an international social fraternity founded on December 26, 1848, at Miami University in Oxford, Ohio. Known for its principles of friendship, sound learning, and moral rectitude, Phi Delta Theta promotes leadership, academic excellence, and community service among its members. The fraternity emphasizes lifelong brotherhood and personal development, operating under the motto "Become the greatest version of yourself." With chapters across North America, Phi Delta Theta maintains', 'phidelt', 'Active', '{"Fraternity & Sorority","Service","Sport","Career Planning","Social"}', '{"career","leadership","service","sport"}'),
  ('134511', 'Hermanas Unidas', 'Hermanas Unidas de CSUF was established in December 2003. We are a nonprofit organization that enocurages latinas within higher education to build community, leadership, and thrive in academics together.', 'We are a statewide incorporated organization that runs from Humboldt to San Diego. We are a large support system and resource for individuals in the higher education. We provide this opportunity to our members by consisting of three pillars, which include community service, academics and social networking. HaU de CSUF will create empowering and welcoming spaces by encouraging others to be their true selves, promoting siblinghood, and being understanding of everyone''s situation to obtain self gro', 'hermanasunidas', 'Active', '{"Cultural","Service","Social"}', '{"cultural","leadership","service"}'),
  ('429952', 'Nurses for Sexual and Reproductive Health', 'NSRH provides students with the education, tools, and resources necessary to become social-change agents within the healthcare system as it relates to sexual and reproductive justice.', '', 'nsrh', 'Active', '{"Political/Social Action","College of Health and Human Development","Health & Wellness","LGBTQ+"}', '{"health-wellness","lgbtq","political-social-action"}'),
  ('415278', 'Gensei Ryu USA Karate', 'We are a non-profit karate organization. We have dedicated our time to being there for the community by providing low cost classes and teaching martial arts to whoever is interested. We are extending our organization to do the same and more at CSUF.', '', 'gensei_ryu_usa_karate', 'Active', '{"Special Interest","Sport","Recreation","Health & Wellness","Social"}', '{"health-wellness","recreation","sport"}'),
  ('349722', 'Turning Point USA at California State University, Fullerton', 'Turning Point USA is a 501(c)3 non-profit organization. The organization’s mission is to identify, educate, train, and organize students to promote the principles of freedom, free markets, and limited government.', 'Turning Point USA: Igniting the Flame of Freedom 🚀🔥 At Turning Point USA, we''re on a mission! Our goal is to educate and empower the next generation of leaders about the pillars of fiscal responsibility, free markets 📈, and the value of limited government. 📚 Educate : TPUSA takes education to the next level! We''re all about educating students about the importance of freedom, free markets, and limited government. 🔎 Identify : TPUSA finds student activists across the country who believe in limited', 'turning_point_usa_csuf', 'Active', '{"Cultural","Political/Social Action","Service","Special Interest","Social"}', '{"cultural","political-social-action","service"}'),
  ('331331', 'Delta Epsilon Mu - Beta Alpha Chapter', 'Delta Epsilon Mu is the nation''s premier Professional Pre-Health Co-Ed Fraternity. Our organization works with pre-health students across medicine, dentistry, nursing, psychology, physical therapy, veterinary, and allied health studies.', 'Delta Epsilon Mu is the nation''s premier professional pre-health co-ed fraternity. Our fraternity seeks to unite students of diverse backgrounds and pre-health interests under the pillars of Loyalty, Dedication, Friendship, and Support. Along with our four pillars, the Beta Alpha Chapter has created a positive, inclusive, and supportive space, filled with opportunities and resources, for our members to grow throughout their undergraduate path and flourish as they enter the pre-health field to cr', 'dembetaalpha', 'Active', '{"Fraternity & Sorority","Service","Career Planning","College of Health and Human Development","College of Humanities & Social Sciences","College of Natural Science and Mathematics","Health & Wellness","Social"}', '{"career","health-wellness","service"}'),
  ('134719', 'TitanTHON: A Miracle Network Dance Marathon', 'TitanTHON is one of 400+ Miracle Network Dance Marathons across the United States and Canada! By raising funds for our local CHOC Children''s hospital, we are equipped to change kids'' health. Kids can''t wait so neither should you.', 'Through Miracle Network Dance Marathon, students and campus communities have raised $350M for local children''s hospitals since 1991. In the past eight years, TitanTHON has raised over a quarter of a million dollars. Join us in raising $15,000 this year #ForTheKids at Rady Children''s Hospital of Orange County! TitanTHON: A Miracle Network Dance Marathon is a nationwide student-run non-profit organization that raises money for the Children''s Miracle Network Hospital in the community. Throughout th', 'titanthon', 'Active', '{"Service","Special Interest","Recreation","College of Health and Human Development","Social"}', '{"leadership","recreation","service"}'),
  ('332203', 'Nursing Peer Tutoring', 'The purpose of this organization is to advance academic success in nursing courses through proven active learning strategies, peer-to-peer collaboration, and leadership development.', 'The purpose of this organization is to advance academic success in nursing courses through proven active learning strategies, peer-to-peer collaboration, and leadership development. To do this, students who excelled in nursing courses are welcome to apply as tutors and be an extra resource for fellow students. The group tutoring sessions are open to students in the courses and to pre-nursing students who would like an insight into nursing studies.', 'nursingpeertutoring', 'Active', '{"Service","College of Health and Human Development","Health & Wellness"}', '{"health-wellness","leadership","service"}'),
  ('383119', 'Ski and Snowboard Club', 'Welcome to the CSUF Snowboard and Ski Club! Whether you''re a seasoned rider or a first-timer, our inclusive club offers unforgettable experiences on and off the slopes. Join us for regular trips, skill-building, and a vibrant social scene', 'Welcome to the CSUF Snowboard and Ski Club, where snow enthusiasts of all kinds come together to chase powder, embrace the thrill of the slopes, and receive special discounts. About Us: Our club is dedicated to providing a supportive environment where members can improve their techniques, explore new terrains, and enjoy the sheer joy of winter sports. Meetups & Group Rides: Join us for regular outings to the best local resorts and hidden gems. Our group rides cater to all skill levels, from begi', 'skisnowclub', 'Active', '{"Sport","Recreation","Outdoors","Social"}', '{"outdoors","recreation","sport"}')
